-- Generated by scripts/import-knowledge.ts. Review before applying.
begin;

delete from public.knowledge_entries
where source = 'import'
  and tenant_id = (select id from public.tenants where slug = 'elevate');

insert into public.knowledge_entries (tenant_id, kind, title, body, url, source, sort_order)
select t.id, v.kind::public.knowledge_kind, v.title, v.body, v.url, 'import', v.sort_order
from public.tenants t
cross join (values
  ('about', 'Mikael Pretorius — Web developer and designer, Cape Winelands, South Africa', 'Elevate is the web design and development studio of Mikael Pretorius, a freelance web developer and designer based in Stellenbosch, in South Africa’s Cape Winelands. He designs and builds websites in Next.js, React and TypeScript, and takes on work for businesses in Stellenbosch, Paarl, Franschhoek, Wellington and the towns around them.

Website: https://elevate-web.co.za/
Contact: https://elevate-web.co.za/#contact, mikaelpretorius@gmail.com, or WhatsApp / call +27 82 756 3036
Profiles: LinkedIn https://www.linkedin.com/in/mikael-pretorius · GitHub https://github.com/PretoriusMikael · Instagram https://www.instagram.com/mikael_pretorius/', null, 100),
  ('service', 'Landing website', 'One service in one place: a trade, a studio, a guest house, a consultant. One page, or up to three, in 1-2 weeks. From R6,700, the founding-client price (list price R9,600).

- Designed and built in my own system, not from a template
- The motion this site is built with, on your own content
- A contact form and a WhatsApp button
- Set up for Google from the start: titles, descriptions and structured data
- A performance budget, held on a phone on mobile data
- Launched on your own domain', 'https://elevate-web.co.za/services', 101),
  ('service', 'Business website', 'A business with services, prices, a timetable or a menu, and a team. Five to eight pages, in 4-6 weeks. From R10,100, the founding-client price (list price R14,400).

- Everything in the Landing website
- Your brand set up on the site: logo, colours and type
- A menu, timetable or price list, laid out so it is easy to change
- A booking hand-off, or WhatsApp if you would rather keep it simple
- An About page with your story
- Two rounds of design review with you', 'https://elevate-web.co.za/services', 102),
  ('service', 'Multi-location website', 'Several branches, each with its own hours, its own map and its own page. Eight to fifteen or more pages, in 6-10 weeks. Priced after a conversation.

- Everything in the Business website
- A page for every branch, titled for its town so it can be found locally
- Motion or 3D built for you, loaded after the page so the site stays fast
- One integration wired in and styled: a booking vendor, or payments
- Help gathering and organising your content
- A written performance and accessibility report at hand-over', 'https://elevate-web.co.za/services', 103),
  ('service', 'Web app development', 'Logins, dashboards, anything people use rather than read, designed and built to the same standard as the sites. Priced after a conversation.', 'https://elevate-web.co.za/services', 104),
  ('service', '3D and WebGL on the web', 'A scene like the four on this site, on its own or in a site you already have, loaded so the page stays fast. Priced after a conversation.', 'https://elevate-web.co.za/services', 105),
  ('service', 'Care: hosting and upkeep', 'Hosting, your domain renewal, security updates, uptime monitoring, an hour of changes a month, and a report every quarter on what is working. R500 a month.', 'https://elevate-web.co.za/services', 106),
  ('page', 'Barber Club website rebuild', 'This rebuild of the Barber Club website, not yet launched, was designed and built by Mikael Pretorius of Elevate, a web design and development studio in Stellenbosch, in the Cape Winelands.

Barber Club is a group of eleven barber shops in and around the Cape Winelands, trading since December 2017: four in Paarl, three in Stellenbosch, and one each in Wellington, Malmesbury, Durbanville and Franschhoek. This is a rebuild of its website, barberclub.co.za, that I took on and built from the ground up.

A page for every shop:

Someone looking for a barber is looking in one town, so each of the eleven shops has a page of its own: its address, its own opening hours, a map and directions. Each page is titled for its town and carries the structured data search engines use to place a shop locally.

- A finder that filters the shops by town, with a count beside each one
- A badge on every shop that works out whether it is open right now, in South African time
- Classic and Premier side by side behind one toggle, with the real published prices
- Group packages given a page of their own

A 3D landing kept out of first paint:

The landing carries a 3D pair of scissors, and it never enters first paint. The 3D code, three.js with React Three Fiber, sits in a chunk of its own, 229 KB gzipped. It loads only on desktop-class devices, only after the page has painted, and it is unmounted again once it scrolls out of view. Phones get a still image in its place. Slow connections and data-saver get no scissors at all, and visitors who ask for reduced motion get the still.

Both figures were measured on the deployed preview on 21 September 2026: the home page ships 268 KB of JavaScript, gzipped, and the 3D chunk is not in it. Every page is prerendered as static HTML.

Nothing invented:

No star ratings, reviews or barber profiles are shown, or marked up for search engines, until they can be verified. Where a detail about a shop is not confirmed, the page says so in place rather than guessing.

Accessibility:

- A skip link, visible focus on every control, and a lightbox that holds focus and hands it back
- A pinned scroll sequence that is not rendered at all for visitors who ask for reduced motion
- Brass text that holds at least 5.25:1 against the dark ground

Built with: Next.js 16, React 19, TypeScript, Tailwind CSS v4, Motion, three.js with React Three Fiber, Radix.
Preview address (not launched): https://barber-club-seven.vercel.app', 'https://elevate-web.co.za/work/barber-club', 107),
  ('page', 'The Kitchen Pilates Studio website', 'The website for The Kitchen Pilates Studio in Paarl, not yet launched, was designed and built by Mikael Pretorius of Elevate, a web design and development studio in Stellenbosch, in the Cape Winelands.

The Kitchen is a boutique reformer pilates studio on Main Road in Paarl, founded by Sheri Ferreira. It talks like a kitchen: classes are on the menu, instructors are chefs, and every session is graded mild, medium or spicy. The website keeps that voice intact.

In the studio’s own voice:

The headings keep that voice: “What’s on the menu?”, “Meet the chefs”, “Everyone eats here”. Even a timetable with nothing chosen yet says “Nothing plated yet.” A voice this particular is easy to lose, so I treated it as part of the build.

What I built:

- Six pages: home, our story, classes, shop, franchising and contact
- A weekly timetable across six days, filtered by day and by heat
- Each class’s intensity shown as one, two or three chillies
- A shop shelf you can explore: a photograph of the studio’s own shelf, with twelve things on it to pick up

The brand, carried across:

I inventoried every brand file the studio sent, renamed each one to say what it is, and mapped it to where the build uses it. The site’s colours were reconciled to the brand’s exact values.

Motion that steps aside:

The home page opens on a pinned scroll sequence drawn from 120 frames. Every animation on the site, the smooth scrolling included, steps aside for visitors who ask for reduced motion. There is a skip link, and the dialog that confirms a chosen class takes focus and gives it back.

Built with: Next.js 16, React 19, TypeScript, GSAP, CSS Modules.
Preview address (not launched): https://the-kitchen-pilates-studio.vercel.app', 'https://elevate-web.co.za/work/the-kitchen-pilates-studio', 108),
  ('faq', 'Where are you based, and where do you take on work?', 'I’m based in Stellenbosch, in the Cape Winelands of South Africa’s Western Cape, and I take on website design and development for businesses in Stellenbosch, Paarl, Franschhoek, Wellington and the towns around them.', null, 109),
  ('faq', 'Are you a web designer or a web developer?', 'Both. I design and build, so the person who decides how your website looks and feels is the same person who makes it work. There is no hand-over between a designer and a developer.', null, 110),
  ('faq', 'What kinds of websites do you build?', 'Websites for local businesses: the kind with services, prices, locations and a clear way to get in touch. Recent builds are a rebuild of the website of an eleven-branch barber group across the Winelands, with a page for every branch, and a website for a reformer pilates studio in Paarl, with a menu of classes and a timetable you can filter. Neither is launched yet.', null, 111),
  ('faq', 'What do you build with, and why?', 'Next.js, React and TypeScript, with Tailwind CSS for styling and GSAP for motion. Next.js lets me prerender pages as static HTML and hold heavy code back until it is needed, which matters on a phone on mobile data.', null, 112),
  ('faq', 'Will my website be found on Google?', 'Nobody can promise a ranking. What I do is build for it from the start: prerendered pages, a proper title and description on each, and the structured data search engines read. The Barber Club rebuild shows the approach. Each of its eleven shops has a page of its own, titled for its town, so that it can be found locally.', null, 113),
  ('faq', 'What does a website cost?', 'For a business in South Africa, a one-page site is R9,600 and a business site of five to eight pages R14,400, at list price. My first five clients get 30% off, so those start at R6,700 and R10,100. Common set-ups, such as bookings for a salon or a menu and vouchers for a restaurant, come as combos with something off. Sites for several branches, web apps and 3D work are quoted after a conversation. Care, which is hosting, updates and an hour of changes a month, is R500 a month. Half is paid to book a start date and half at launch. Businesses outside South Africa have their own prices, in US dollars; the estimate on this site gives a range for your own project in about two minutes.', null, 114),
  ('faq', 'How do we start?', 'Send me a message through the form on this page, WhatsApp or call me on 082 756 3036, or email mikaelpretorius@gmail.com. A sentence or two about your business and what you’d like the website to do is enough. You don’t need a brief.', null, 115),
  ('page', 'Home page', 'The home page: selected work, the three website packages in brief, how a project runs, a little about Mikael, the questions most people ask, and the contact form.', 'https://elevate-web.co.za/', 116),
  ('page', 'Services and packages', 'Websites in three sizes (Landing, Business, Multi-location), web apps, 3D on the web and monthly Care: what each includes, who it suits and what it costs in rand.', 'https://elevate-web.co.za/services', 117),
  ('page', 'Website cost estimate', 'A free estimate builder. Answer five short questions for a price range in rand, a breakdown and a launch week, in about two minutes. Businesses outside South Africa get their own range. The estimate can be sent to Mikael or used to book a call about it.', 'https://elevate-web.co.za/estimate', 118),
  ('page', 'How a project runs', 'Four steps from a first hello to a site that keeps working, and nothing starts until the price is in writing. 1. A short call: fifteen minutes on a call or on WhatsApp about what the business does and what the site has to do. 2. A written quote: a fixed price and a start date, in writing, before any work begins; half books the date. 3. The build, with you: you see it take shape and say what should change, in rounds of review, before anything goes live. 4. Launch, then Care: it goes live on your own domain and the other half is due; Care keeps it hosted, updated and changing. Your domain is in your own name from the start, half is paid at launch and not before, and everything is handed over if you ever leave.', 'https://elevate-web.co.za/#how', 119),
  ('page', 'About Mikael', 'Mikael Pretorius is a freelance web developer and designer, and Elevate is his studio, based in Stellenbosch in the Cape Winelands of South Africa. He works in Next.js, React and TypeScript, with GSAP for motion, and pays close attention to how a site feels on a phone on mobile data. He quotes in South African rand.', 'https://elevate-web.co.za/#about', 120),
  ('page', 'Where it comes from', 'Four live WebGL scenes drawn in code (a galaxy, a river, a flock and a leaf) and what each one teaches about building a website.', 'https://elevate-web.co.za/inspiration', 121),
  ('page', 'Start a conversation', 'The contact form on the home page. A sentence or two about the business and what the website should do is enough; no brief is needed. Mikael replies within 24 hours. A 15-minute introductory call can also be booked directly.', 'https://elevate-web.co.za/#contact', 122),
  ('page', 'Privacy notice', 'What the website keeps and why, under POPIA: what it does not keep, who handles messages, and how to ask for your information back.', 'https://elevate-web.co.za/privacy', 123)
) as v(kind, title, body, url, sort_order)
where t.slug = 'elevate';

commit;
